function policy(obs, params, mem) {
  var P = params;
  var ta = obs[0], ts = obs[1], hh = obs[4];
  var hipA = obs[5], hipAS = obs[6], kneeA = obs[7], kneeAS = obs[8];
  var hipB = obs[10], hipBS = obs[11], kneeB = obs[12], kneeBS = obs[13];
  var a1 = obs[15], a2 = obs[16], a3 = obs[17], tt = obs[19];
  var TAU = 6.283185307179586;

  var freq = P[0];
  if (!(freq > 0.15)) freq = 0.15;
  if (freq > 6) freq = 6;

  var ramp = tt * 2.5;
  if (ramp > 1) ramp = 1;

  var terr = a1;
  var w = a2 * 0.8;
  if (w > terr) terr = w;
  w = a3 * 0.45;
  if (w > terr) terr = w;
  if (!(terr > 0)) terr = 0;
  if (terr > 0.55) terr = 0.55;

  var bal = P[16] * ta - P[17] * ts;
  if (!isFinite(bal)) bal = 0;

  var hAdj = P[18] * (P[19] - hh);
  if (!isFinite(hAdj)) hAdj = 0;
  if (hAdj > 0.55) hAdj = 0.55;
  if (hAdj < -0.55) hAdj = -0.55;

  var base = TAU * freq * tt + P[1];
  var offs = P[22];
  var q = [hipA, hipAS, kneeA, kneeAS, hipB, hipBS, kneeB, kneeBS];
  var out = [0, 0, 0, 0];

  for (var L = 0; L < 2; L++) {
    var ph = base + (L ? offs : 0);
    var c1 = Math.cos(ph), s1 = Math.sin(ph);
    var c2 = c1 * c1 - s1 * s1, s2 = 2 * c1 * s1;

    var hd = P[2] + ramp * (P[3] * c1 + P[4] * s1 + P[5] * c2 + P[6] * s2);
    var kd = P[7] + ramp * (P[8] * c1 + P[9] * s1 + P[10] * c2 + P[11] * s2);

    var sw = -s1;
    if (sw < 0) sw = 0;

    kd -= P[20] * terr * sw;
    hd += P[21] * terr * sw;
    kd += P[23] * terr * (1 - sw);
    kd += hAdj;

    if (hd > 1.12) hd = 1.12; else if (hd < -0.82) hd = -0.82;
    if (kd > -0.075) kd = -0.075; else if (kd < -1.4) kd = -1.4;

    var i0 = L * 4;
    var uH = P[12] * (hd - q[i0]) - P[13] * q[i0 + 1] + bal;
    var uK = P[14] * (kd - q[i0 + 2]) - P[15] * q[i0 + 3];

    out[L * 2] = uH * 0.006211180124223602;
    out[L * 2 + 1] = uK * 0.004830917874396135;
  }

  for (var i = 0; i < 4; i++) {
    var u = out[i];
    if (!isFinite(u)) u = 0;
    if (u > 1) u = 1; else if (u < -1) u = -1;
    out[i] = u;
  }
  return out;
}

function learn(lab) {
  var DIM = 24;
  var TAU = 6.283185307179586;

  var INIT = [1.55, 0.0, 0.03, 0.48, 0.08, 0.0, 0.0, -0.43, 0.10, 0.40, 0.18, 0.0,
              320, 45, 420, 50, 240, 45, 2.0, 1.02, 2.2, 0.25, 3.141592653589793, 1.0];
  var LO = [0.8, -2.5, -0.35, -0.9, -0.45, -0.3, -0.3, -0.95, -0.5, -0.3, -0.35, -0.45,
            -1200, -250, -1400, -300, -900, -250, -8, 0.65, -1.5, -1.5, 0.6, -2.0];
  var HI = [3.2, 2.5, 0.55, 0.9, 0.5, 0.35, 0.35, -0.1, 0.55, 0.85, 0.55, 0.45,
            1200, 250, 1400, 300, 900, 250, 8, 1.3, 5.5, 2.5, 5.68, 4.0];
  var SIG = [0.28, 0.55, 0.13, 0.15, 0.13, 0.09, 0.09, 0.13, 0.13, 0.14, 0.13, 0.11,
             110, 25, 120, 28, 110, 28, 1.5, 0.09, 0.9, 0.55, 0.55, 0.8];

  var bestP = null, bestF = -1e300, used = 0, t0 = 0, DUR = 10;
  var costEMA = 0.3;

  try { t0 = Date.now(); } catch (e) { t0 = 0; }
  try {
    if (lab && typeof lab.seconds === 'number' && lab.seconds > 0) DUR = lab.seconds;
  } catch (e) {}

  function nowMs() {
    var x = 0;
    try { x = Date.now(); } catch (e) {}
    return x;
  }
  function elapsed() {
    return t0 ? (nowMs() - t0) * 0.001 : 0;
  }
  function left() {
    var l = null;
    try { l = lab.trialsLeft(); } catch (e) { return 1e9; }
    return (typeof l === 'number' && isFinite(l)) ? l : 1e9;
  }
  function canRun() {
    if (left() <= 0) return false;
    if (!t0) return true;
    var e = elapsed();
    if (e > 156) return false;
    if (e + costEMA * 2.5 > 173) return false;
    return true;
  }
  function clipP(p) {
    for (var i = 0; i < DIM; i++) {
      var v = p[i];
      if (!isFinite(v)) v = INIT[i];
      if (v < LO[i]) v = LO[i];
      else if (v > HI[i]) v = HI[i];
      p[i] = v;
    }
    return p;
  }
  function gauss() {
    var u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(TAU * v);
  }
  function evalF(p) {
    if (!canRun()) return null;
    var tA = nowMs();
    var r = null;
    try { r = lab.trial(p); } catch (e) { r = null; }
    used++;
    if (t0) {
      var dt = (nowMs() - tA) * 0.001;
      costEMA = 0.82 * costEMA + 0.18 * (dt > 0 ? dt : 0);
      if (dt > costEMA) costEMA = dt;
    }
    if (!r) return null;
    var d = r.distance;
    if (typeof d !== 'number' || !isFinite(d) || d < 0) d = 0;
    var f = d;
    var oc = r.outcome;
    if (oc === 'finished') {
      var tr = r.time;
      if (typeof tr === 'number' && isFinite(tr)) f += 0.6 * (DUR - tr);
    } else if (oc === 'invalid' || oc === 'error') {
      f = -1000;
    }
    if (f > bestF) { bestF = f; bestP = p.slice(); }
    return f;
  }

  function localSearch(x, curF, stepScale) {
    var steps = [];
    for (var i = 0; i < DIM; i++) steps[i] = SIG[i] * stepScale;
    for (var sweep = 0; sweep < 32 && canRun(); sweep++) {
      var improved = false;
      for (var i = 0; i < DIM && canRun(); i++) {
        for (var s = -1; s <= 1; s += 2) {
          var p = x.slice();
          p[i] += s * steps[i];
          clipP(p);
          var f = evalF(p);
          if (f !== null && f > curF) {
            x = p.slice();
            curF = f;
            improved = true;
          }
        }
      }
      if (!improved) {
        var small = true;
        for (var i = 0; i < DIM; i++) {
          steps[i] *= 0.5;
          if (steps[i] > SIG[i] * 0.025) small = false;
        }
        if (small) break;
      }
    }
    return x;
  }

  // ---- Stage 0 : hand-made seeds ----
  var seeds = [];
  var fq = [1.15, 1.4, 1.65, 1.9, 2.15];
  for (var si = 0; si < fq.length; si++) {
    var f = fq[si];
    var p = INIT.slice(); p[0] = f; seeds.push(p);
    p = INIT.slice(); p[0] = f * 0.92; p[3] = 0.62; p[7] = -0.5; p[9] = 0.5; seeds.push(p);
    p = INIT.slice(); p[0] = f * 1.12; p[3] = 0.32; p[7] = -0.34; p[9] = 0.28; seeds.push(p);
    p = INIT.slice(); p[0] = f; p[16] = -240; p[17] = -45; seeds.push(p);
    p = INIT.slice(); p[0] = f; p[22] = 0.0; seeds.push(p);
  }
  for (var si = 0; si < seeds.length && canRun(); si++) evalF(seeds[si]);

  // ---- Stage 1 : random screening around the prior ----
  for (var si = 0; si < 55 && canRun(); si++) {
    var p = [];
    for (var j = 0; j < DIM; j++) p.push(INIT[j] + gauss() * SIG[j] * 1.1);
    evalF(clipP(p));
  }

  // ---- Stage 2 : cross-entropy refinement ----
  var mean = bestP ? bestP.slice() : INIT.slice();
  var sd = [];
  for (var j = 0; j < DIM; j++) sd[j] = SIG[j] * 0.55;
  for (var iter = 0; iter < 45 && canRun(); iter++) {
    var pop = [];
    for (var j = 0; j < 20 && canRun(); j++) {
      var p = [];
      for (var k = 0; k < DIM; k++) p.push(mean[k] + gauss() * sd[k]);
      clipP(p);
      var f = evalF(p);
      if (f === null) break;
      pop.push({ p: p, f: f });
    }
    if (pop.length < 5) break;
    pop.sort(function (a, b) { return b.f - a.f; });
    var nE = Math.max(3, Math.ceil(pop.length * 0.22));
    for (var k = 0; k < DIM; k++) {
      var m = 0, v2 = 0, j;
      for (j = 0; j < nE; j++) m += pop[j].p[k];
      m /= nE;
      for (j = 0; j < nE; j++) {
        var dd = pop[j].p[k] - m;
        v2 += dd * dd;
      }
      var s2 = Math.sqrt(v2 / nE);
      mean[k] = 0.45 * mean[k] + 0.55 * m;
      var ns = 0.72 * sd[k] + 0.28 * (s2 + SIG[k] * 0.07);
      if (ns < SIG[k] * 0.03) ns = SIG[k] * 0.03;
      if (ns > SIG[k] * 1.5) ns = SIG[k] * 1.5;
      sd[k] = ns;
    }
  }

  // ---- Stage 3 : pattern search on the best so far ----
  if (bestP) localSearch(bestP.slice(), bestF, 0.3);

  // ---- Stage 4 : kicked restarts ----
  for (var rr = 0; rr < 5 && canRun(); rr++) {
    if (!bestP) break;
    var x = bestP.slice();
    for (var j = 0; j < DIM; j++) x[j] += gauss() * SIG[j] * 0.55;
    clipP(x);
    var f = evalF(x);
    if (f === null) break;
    localSearch(x, f, 0.22);
  }

  return bestP ? bestP.slice() : INIT.slice();
}

function policy(obs, params, mem) {
  var P = params;
  if (!P || P.length < 16) P = [1.6,0.1,0.5,-0.5,0.35,3.141592653589793,300,25,400,20,-250,-80,1.5,1,1,-0.08];
  var TAU = 6.283185307179586;
  var ta = obs[0], ts = obs[1];
  var hh = obs[4];
  var hA = obs[5], hsA = obs[6], kA = obs[7], ksA = obs[8];
  var hB = obs[10], hsB = obs[11], kB = obs[12], ksB = obs[13];
  var a1 = obs[15], a2 = obs[16], a3 = obs[17];
  var tt = obs[19];
  var freq = P[0]; if (!(freq > 0.25)) freq = 0.25; if (freq > 4) freq = 4;
  var hipOff = P[1];
  var hipAmp = P[2]; if (!(hipAmp > 0)) hipAmp = 0;
  var kneeOff = P[3];
  var kneeAmp = P[4]; if (!(kneeAmp > 0)) kneeAmp = 0;
  var kneePh = P[5];
  var kpH = P[6]; if (!(kpH > 1)) kpH = 1;
  var kdH = P[7]; if (!(kdH >= 0)) kdH = 0;
  var kpK = P[8]; if (!(kpK > 1)) kpK = 1;
  var kdK = P[9]; if (!(kdK >= 0)) kdK = 0;
  var balP = P[10], balD = P[11];
  var hGain = P[12], targetH = P[13];
  var rampT = P[14]; if (!(rampT > 0.05)) rampT = 0.05;
  var tLean = P[15];
  var ramp = tt / rampT; if (ramp > 1) ramp = 1;
  var terr = Math.max(0, Math.max(a1, a2 * 0.75, a3 * 0.4));
  if (terr > 0.5) terr = 0.5;
  var phase = TAU * freq * tt;
  var bal = balP * (ta - tLean) + balD * ts;
  if (!isFinite(bal)) bal = 0;
  var hAdj = hGain * (targetH - hh);
  if (!isFinite(hAdj)) hAdj = 0;
  if (hAdj > 0.5) hAdj = 0.5;
  if (hAdj < -0.5) hAdj = -0.5;
  var trL = -a1 * 0.12;
  if (!isFinite(trL)) trL = 0;
  var hips = [hA, hB], hs = [hsA, hsB];
  var knees = [kA, kB], ks = [ksA, ksB];
  var out = [0, 0, 0, 0];
  for (var L = 0; L < 2; L++) {
    var ph = phase + L * Math.PI;
    var s = Math.sin(ph);
    var hd = hipOff + ramp * hipAmp * s + trL;
    var kd = kneeOff + ramp * kneeAmp * Math.sin(ph + kneePh);
    var swF = s > 0 ? s : 0;
    kd -= terr * swF * 1.5;
    kd += hAdj;
    if (hd > 1.12) hd = 1.12; else if (hd < -0.82) hd = -0.82;
    if (kd > -0.075) kd = -0.075; else if (kd < -1.5) kd = -1.5;
    var uH = kpH * (hd - hips[L]) - kdH * hs[L] + bal;
    var uK = kpK * (kd - knees[L]) - kdK * ks[L];
    out[L * 2] = uH / 161;
    out[L * 2 + 1] = uK / 207;
  }
  for (var i = 0; i < 4; i++) {
    if (!isFinite(out[i])) out[i] = 0;
    if (out[i] > 1) out[i] = 1; else if (out[i] < -1) out[i] = -1;
  }
  return out;
}

function learn(lab) {
  var DIM = 16, TAU = 6.283185307179586;
  var LO = [0.3,-0.3,0.05,-1.15,0.05,-TAU,50,3,50,3,-600,-250,-4,0.55,0.15,-0.25];
  var HI = [3.5,0.55,0.95,-0.12,1.0,TAU,900,100,1200,100,350,350,4,1.35,2.5,0.15];
  var INIT = [1.6,0.1,0.5,-0.5,0.35,3.141592653589793,300,25,400,20,-250,-80,1.5,1.0,1.0,-0.08];
  var SIG = [];
  for (var i = 0; i < DIM; i++) SIG[i] = (HI[i] - LO[i]) * 0.25;
  var bestP = null, bestF = -1e300, used = 0, t0 = 0;
  try { t0 = Date.now(); } catch(e) {}
  function elapsed() { try { return (Date.now() - t0) * 0.001; } catch(e) { return 0; } }
  function gauss() {
    var u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(TAU * v);
  }
  function clipP(p) {
    for (var i = 0; i < DIM; i++) {
      if (!isFinite(p[i])) p[i] = INIT[i];
      if (p[i] < LO[i]) p[i] = LO[i]; else if (p[i] > HI[i]) p[i] = HI[i];
    }
    return p;
  }
  function evalF(p) {
    if (used >= 1000) return null;
    try { if (lab.trialsLeft && lab.trialsLeft() <= 0) return null; } catch(e) {}
    clipP(p);
    var r = null;
    try { r = lab.trial(p); } catch(e) {}
    used++;
    if (!r) return null;
    var f = r.distance;
    if (!isFinite(f) || f < 0) f = 0;
    if (r.outcome === 'invalid' || r.outcome === 'error') f = -1000;
    if (f > bestF) { bestF = f; bestP = p.slice(); }
    return f;
  }
  var seeds = [];
  var freqs = [1.0, 1.3, 1.6, 1.9, 2.2, 2.5];
  for (var fi = 0; fi < freqs.length; fi++)
    for (var ai = 0; ai < 3; ai++) {
      var p = INIT.slice();
      p[0] = freqs[fi]; p[2] = [0.3, 0.5, 0.7][ai]; p[4] = p[2] * 0.65;
      seeds.push(p);
    }
  var kphs = [-4.71, -3.14, -1.57, 0, 1.57, 3.14, 4.71];
  for (var ki = 0; ki < kphs.length; ki++) {
    var p = INIT.slice(); p[5] = kphs[ki]; seeds.push(p);
  }
  var gainSeeds = [
    [400,20,500,25,-300,-60],
    [200,40,300,40,-150,-100],
    [600,15,800,15,-400,-40]
  ];
  for (var gi = 0; gi < gainSeeds.length; gi++) {
    var p = INIT.slice();
    p[6] = gainSeeds[gi][0]; p[7] = gainSeeds[gi][1];
    p[8] = gainSeeds[gi][2]; p[9] = gainSeeds[gi][3];
    p[10] = gainSeeds[gi][4]; p[11] = gainSeeds[gi][5];
    seeds.push(p);
  }
  for (var si = 0; si < seeds.length && used < 1000 && elapsed() < 148; si++) evalF(seeds[si]);
  for (var si = 0; si < 55 && used < 1000 && elapsed() < 148; si++) {
    var p = [];
    for (var j = 0; j < DIM; j++) p.push(INIT[j] + gauss() * SIG[j] * 1.1);
    evalF(p);
  }
  var m = (bestP || INIT).slice(), sd = [];
  for (var j = 0; j < DIM; j++) sd[j] = SIG[j] * 0.55;
  var lam = 18, mu = 5, stg = 0, prevF = bestF, restarts = 0;
  for (var gen = 0; gen < 42 && used < 1000 && elapsed() < 156; gen++) {
    var pop = [];
    for (var k = 0; k < lam && used < 1000; k++) {
      var p = [];
      for (var i = 0; i < DIM; i++) p.push(m[i] + gauss() * sd[i]);
      var f = evalF(p);
      if (f === null) break;
      pop.push({ p: p, f: f });
    }
    if (pop.length < 3) break;
    pop.sort(function(a, b) { return b.f - a.f; });
    var nm = [];
    for (var i = 0; i < DIM; i++) {
      nm[i] = 0;
      for (var k = 0; k < mu && k < pop.length; k++) nm[i] += pop[k].p[i];
