      const r = lab.trial(q);
      if (!r) return -1;
      if (r.outcome === 'invalid' || r.outcome === 'error') return -1;
      const d = Number(r.distance);
      return isFinite(d) ? d : -1;
    } catch (e) {
      return -1;
    }
