    const s1 = Math.sin(phi);
    const c1 = Math.cos(phi);
    const s2 = Math.sin(2 * phi + num(p.h2p));
    const sw = Math.max(0, Math.sin(phi + num(p.kph)));
    const kc = Math.cos(phi + num(p.kph2));

    let hT = num(p.hm) + num(p.ha) * s1 + num(p.hc) * c1 + num(p.h2) * s2 + lean
           + (foot ? num(p.hf) : 0);
    hT = clamp(hT, -0.85, 1.1);

    let kT = num(p.km) + num(p.kw) * sw + num(p.ka) * kc + hz
           + (foot ? num(p.kf) : 0);
    kT = clamp(kT, -1.65, -0.08);

    const o1 = clamp(kp * (hT - hip) - kd * hipS, -1, 1);
    const o2 = clamp(kp * (kT - knee) - kd * kneeS, -1, 1);
    return [o1, o2];
  }

  const footA = num(obs[9]) > 0.5;
  const footB = num(obs[14]) > 0.5;
  const A = leg(ph, num(obs[5]), num(obs[6]), num(obs[7]), num(obs[8]), footA);
  const B = leg(ph + num(p.legOff), num(obs[10]), num(obs[11]), num(obs[12]), num(obs[13]), footB);
  return [A[0], A[1], B[0], B[1]];
}

function learn(lab) {
  const SPEC = [
    ['f', 0.5, 4.5],
    ['fv', -1, 1],
    ['vr', 0, 4],
    ['hm', -0.6, 0.6],
    ['ha', -1.2, 1.2],
    ['hc', -0.8, 0.8],
    ['h2', -0.5, 0.5],
    ['h2p', -Math.PI, Math.PI],
    ['km', -1.6, -0.2],
    ['kw', -1.2, 1.2],
    ['kph', -Math.PI, Math.PI],
    ['ka', -0.9, 0.9],
    ['kph2', -Math.PI, Math.PI],
    ['legOff', -Math.PI, Math.PI],
    ['kp', 3, 20],
    ['kd', 0, 0.6],
    ['bal', -4, 4],
    ['balD', -1, 1],
    ['vg', -1, 1],
    ['hz', -2, 2],
    ['hf', -0.5, 0.5],
    ['kf', -0.5, 0.5]
  ];
  const n = SPEC.length;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const gauss = () => {
    let u = 0;
    while (u === 0) u = Math.random();
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };

  const hasClock = (typeof Date !== 'undefined' && typeof Date.now === 'function');
  const t0 = hasClock ? Date.now() : 0;
  const elapsed = () => (hasClock ? (Date.now() - t0) / 1000 : 0);

  const toReal = (x) => {
    const q = {};
    for (let i = 0; i < n; i++) {
      const lo = SPEC[i][1], hi = SPEC[i][2];
      q[SPEC[i][0]] = lo + clamp01(x[i]) * (hi - lo);
    }
    return q;
  };
  const toNorm = (q) => {
    const x = new Array(n);
    for (let i = 0; i < n; i++) {
      const k = SPEC[i][0], lo = SPEC[i][1], hi = SPEC[i][2];
      const v = (typeof q[k] === 'number' && isFinite(q[k])) ? q[k] : (lo + hi) / 2;
      x[i] = clamp01((v - lo) / (hi - lo));
    }
    return x;
  };

  let bestP = null;
  let bestF = -Infinity;
  let bestX = null;
  let done = false;

  function fit(x) {
    if (done) return null;
    if (elapsed() > 150) { done = true; return null; }
    let left = 0;
    try { left = lab.trialsLeft(); } catch (e) { left = 0; }
    if (!(left > 0)) { done = true; return null; }
    const q = toReal(x);
    let d = -1;
    try {
      const r = lab.trial(q);
      if (r && r.outcome !== 'invalid' && r.outcome !== 'error') {
        const v = Number(r.distance);
        if (isFinite(v)) d = v;
      }
    } catch (e) {
      d = -1;
    }
    if (d > bestF) {
      bestF = d;
      bestP = Object.assign({}, q);
      bestX = x.slice();
    }
    return d;
  }

  // Separable CMA-ES on the unit cube (maximising distance)
  function cmaRun(m0, sigma0, lam) {
    const mu = Math.floor(lam / 2);
    const w = [];
    let sw = 0;
    for (let i = 0; i < mu; i++) { w.push(Math.log(mu + 0.5) - Math.log(i + 1)); sw += w[i]; }
    for (let i = 0; i < mu; i++) w[i] /= sw;
    let mueff = 0;
    for (const v of w) mueff += v * v;
    mueff = 1 / mueff;

    const cs = (mueff + 2) / (n + mueff + 5);
    const damps = 1 + 2 * Math.max(0, Math.sqrt((mueff - 1) / (n + 1)) - 1) + cs;
    const cc = (4 + mueff / n) / (n + 4 + 2 * mueff / n);
    const fac = (n + 2) / 3;
    const c1 = Math.min(1, fac * 2 / ((n + 1.3) * (n + 1.3) + mueff));
    const cmu = Math.min(1 - c1, fac * 2 * (mueff - 2 + 1 / mueff) / ((n + 2) * (n + 2) + mueff));
    const chiN = Math.sqrt(n) * (1 - 1 / (4 * n) + 1 / (21 * n * n));

    const m = m0.slice();
    let sigma = sigma0;
    const dC = new Array(n).fill(1);
    const pc = new Array(n).fill(0);
    const ps = new Array(n).fill(0);
    let runBest = -Infinity;
    let stag = 0;
    let gen = 0;

    while (!done) {
      gen++;
      const pop = [];
      for (let k = 0; k < lam; k++) {
        const y = new Array(n);
        const x = new Array(n);
        for (let i = 0; i < n; i++) {
          y[i] = Math.sqrt(dC[i]) * gauss();
          x[i] = m[i] + sigma * y[i];
        }
        const fv = fit(x.map(clamp01));
        if (fv === null) return;
        pop.push({ y: y, f: fv });
      }
      pop.sort((a, b) => b.f - a.f);

      const yw = new Array(n).fill(0);
      for (let j = 0; j < mu; j++) {
        for (let i = 0; i < n; i++) yw[i] += w[j] * pop[j].y[i];
      }
      for (let i = 0; i < n; i++) m[i] = clamp01(m[i] + sigma * yw[i]);

      const sq = Math.sqrt(cs * (2 - cs) * mueff);
      let psn2 = 0;
      for (let i = 0; i < n; i++) {
        ps[i] = (1 - cs) * ps[i] + sq * yw[i] / Math.sqrt(dC[i]);
        psn2 += ps[i] * ps[i];
      }
      const psn = Math.sqrt(psn2);
      const hsig = (psn / Math.sqrt(1 - Math.pow(1 - cs, 2 * gen)) / chiN) < (1.4 + 2 / (n + 1)) ? 1 : 0;
      const sqc = Math.sqrt(cc * (2 - cc) * mueff);
      for (let i = 0; i < n; i++) {
        pc[i] = (1 - cc) * pc[i] + hsig * sqc * yw[i];
        let rank = 0;
        for (let j = 0; j < mu; j++) rank += w[j] * pop[j].y[i] * pop[j].y[i];
        let v = (1 - c1 - cmu) * dC[i] + c1 * (pc[i] * pc[i] + (1 - hsig) * cc * (2 - cc) * dC[i]) + cmu * rank;
        dC[i] = Math.min(100, Math.max(1e-8, v));
      }
      sigma *= Math.exp((cs / damps) * (psn / chiN - 1));
      sigma = Math.min(1, Math.max(1e-5, sigma));

      if (pop[0].f > runBest + 1e-9) { runBest = pop[0].f; stag = 0; } else { stag++; }
      if (stag >= 12) return;
      let maxS = 0;
      for (let i = 0; i < n; i++) if (dC[i] > maxS) maxS = dC[i];
      if (sigma * Math.sqrt(maxS) < 1e-4) return;
    }
  }

  // Attempt 7's best params (16.07 m in the race)
  const seed = {
    f: 4.187920809653539,
    fv: -0.014193532676329057,
    vr: 1.7512555582670355,
    hm: -0.39140927917117074,
    ha: -1.0070217432367594,
    hc: -0.7061429652183036,
    h2: 0.042159785203103706,
    h2p: -3.141592653589793,
    km: -0.9819927887795582,
    kw: 0.22219772624972833,
    kph: 1.8458993336117988,
    ka: 0.45857634354467736,
    kph2: -1.081319819045511,
    legOff: -2.9121100157036053,
    kp: 13.186161248353901,
    kd: 0.2579263868991206,
    bal: -1.6061341480361335,
    balD: -0.18302138096324994,
    vg: 0.5289050846118561,
    hz: 0.2945249163908419,
    hf: -0.32200752388780396,
    kf: 0.13918436874026374
  };

  try {
    const x0 = toNorm(seed);
    fit(x0);

    // Fine local refinement around the seed
    let lam = 12;
    cmaRun(x0, 0.04, lam);

    let restart = 0;
    while (!done) {
      restart++;
      lam = Math.min(40, Math.round(lam * 1.3));
      let m0, s0;
      if (restart % 3 === 1 && bestX) {
        m0 = bestX.slice(); s0 = 0.06;
      } else if (restart % 3 === 2 && bestX) {
        m0 = bestX.slice(); s0 = 0.18;
      } else {
        m0 = [];
        for (let i = 0; i < n; i++) m0.push(Math.random());
        s0 = 0.3;
      }
      cmaRun(m0, s0, lam);
    }
  } catch (e) {
    // fall through and return the best found so far
  }

  return bestP || seed;
}
